insert into public.exercises (id, business_id, name, video_length, coaching_notes, steps, easier, harder, tags) values ('c7d8cdf8-ac5f-5976-a6ef-5f0105156478', '7a1e5b0d-0000-4000-a000-000000000001', 'Goblet squat', '0:22', 'Hold the dumbbell close to your chest. Sit back like there is a chair behind you and keep your knees in line with your toes.', array['Stand with feet just wider than hips.', 'Hold the weight at your chest.', 'Sit down and back until your thighs are level.', 'Push through your heels to stand.']::text[], 'Squat to a chair and stand back up', 'Pause for 2 seconds at the bottom', array['legs', 'strength']::text[]) on conflict (id) do nothing;
insert into public.exercises (id, business_id, name, video_length, coaching_notes, steps, easier, harder, tags) values ('14a308cd-0251-5bbf-a03a-9d379cbc0376', '7a1e5b0d-0000-4000-a000-000000000001', 'Romanian deadlift', '0:19', 'Soft knees, push your hips back and keep the weights close to your legs. You should feel it in the back of your thighs.', array['Hold the dumbbells in front of your thighs.', 'Push your hips back with a flat back.', 'Lower to just below the knee.', 'Squeeze your bum to stand tall.']::text[], 'Use lighter weights and a shorter range', 'Single-leg version', array['legs', 'strength']::text[]) on conflict (id) do nothing;
insert into public.exercises (id, business_id, name, video_length, coaching_notes, steps, easier, harder, tags) values ('ea87e5eb-6614-5a2d-a8fe-ea0b52be8c9e', '7a1e5b0d-0000-4000-a000-000000000001', 'Walking lunge', '0:16', 'Long step, drop the back knee gently towards the floor and keep your chest up.', array['Step forward with one leg.', 'Lower until both knees are bent.', 'Push off and bring the back foot through.', 'Repeat on the other side.']::text[], 'Static split squat holding a wall', 'Hold dumbbells', array['legs']::text[]) on conflict (id) do nothing;
insert into public.exercises (id, business_id, name, video_length, coaching_notes, steps, easier, harder, tags) values ('1ca7d9bd-9160-5ba8-aa9b-89b89193589e', '7a1e5b0d-0000-4000-a000-000000000001', 'Glute bridge', '0:14', 'Feet flat, push through your heels and squeeze at the top. Do not arch your lower back.', array['Lie on your back with knees bent.', 'Lift your hips until your body is in a line.', 'Hold for a second.', 'Lower slowly.']::text[], 'Smaller range', 'Single leg', array['legs', 'rehab']::text[]) on conflict (id) do nothing;
insert into public.exercises (id, business_id, name, video_length, coaching_notes, steps, easier, harder, tags) values ('0c6b6001-9703-54c0-a10d-94511027a29f', '7a1e5b0d-0000-4000-a000-000000000001', 'Calf raise', '0:12', 'Rise up slowly onto your toes and lower under control. Hold a wall or counter for balance.', array['Stand tall near a wall.', 'Rise onto your toes.', 'Pause at the top.', 'Lower for 3 seconds.']::text[], 'Both hands on the wall', 'One leg at a time', array['legs', 'balance']::text[]) on conflict (id) do nothing;
insert into public.exercises (id, business_id, name, video_length, coaching_notes, steps, easier, harder, tags) values ('339bf298-6646-5df0-af27-a263edddb612', '7a1e5b0d-0000-4000-a000-000000000001', 'Dead bug', '0:18', 'Press your lower back into the floor the whole time. Move slowly and breathe out as you reach.', array['Lie on your back, arms up, knees over hips.', 'Lower opposite arm and leg.', 'Return to the start.', 'Swap sides.']::text[], 'Move legs only', 'Hold a light weight', array['core']::text[]) on conflict (id) do nothing;
insert into public.exercises (id, business_id, name, video_length, coaching_notes, steps, easier, harder, tags) values ('bd717f82-491d-570f-a00c-4d5232b9b70b', '7a1e5b0d-0000-4000-a000-000000000001', 'Step-up', '0:20', 'Whole foot on the step. Drive up through the front heel and step down with control.', array['Place one foot on the step.', 'Push up to stand on the step.', 'Step down slowly.', 'Do all reps then swap legs.']::text[], 'Lower step and hold a rail', 'Hold dumbbells', array['legs', 'rehab']::text[]) on conflict (id) do nothing;
insert into public.exercises (id, business_id, name, video_length, coaching_notes, steps, easier, harder, tags) values ('7055cad6-8f83-5d7a-aeac-5a3d9ee97071', '7a1e5b0d-0000-4000-a000-000000000001', 'Incline push-up', '0:15', 'Hands on a bench or kitchen counter, body in a straight line, lower your chest to the edge.', array['Hands shoulder width on the bench.', 'Walk your feet back.', 'Lower your chest towards the bench.', 'Push back up.']::text[], 'Use a wall', 'Floor push-up', array['upper']::text[]) on conflict (id) do nothing;
insert into public.exercises (id, business_id, name, video_length, coaching_notes, steps, easier, harder, tags) values ('6776cb11-a400-538b-a05b-44eb4842527b', '7a1e5b0d-0000-4000-a000-000000000001', 'Dumbbell row', '0:17', 'Flat back, pull your elbow towards your hip and squeeze your shoulder blade.', array['One hand and knee on the bench.', 'Let the weight hang.', 'Pull the elbow back.', 'Lower slowly.']::text[], 'Lighter weight', 'Pause at the top', array['upper']::text[]) on conflict (id) do nothing;
insert into public.exercises (id, business_id, name, video_length, coaching_notes, steps, easier, harder, tags) values ('0426757f-6cf1-5dfd-a417-8d358d91194f', '7a1e5b0d-0000-4000-a000-000000000001', 'Shoulder press', '0:15', 'Ribs down, press straight up without leaning back.', array['Weights at shoulder height.', 'Press up until arms are straight.', 'Lower to your shoulders.']::text[], 'Seated', 'Standing on one leg', array['upper']::text[]) on conflict (id) do nothing;
insert into public.exercises (id, business_id, name, video_length, coaching_notes, steps, easier, harder, tags) values ('075ed950-4b48-5ca5-a05b-46bc03fa0a07', '7a1e5b0d-0000-4000-a000-000000000001', 'Cat cow', '0:20', 'Move slowly with your breath. Round up as you breathe out, dip down as you breathe in.', array['Hands and knees on the floor.', 'Round your back up.', 'Let your tummy drop and look forward.']::text[], 'Seated on a chair', null, array['mobility']::text[]) on conflict (id) do nothing;
insert into public.exercises (id, business_id, name, video_length, coaching_notes, steps, easier, harder, tags) values ('d664b71b-8ff7-56a8-aafe-f967ef2e3e9a', '7a1e5b0d-0000-4000-a000-000000000001', 'Thread the needle', '0:18', 'Reach under and rotate gently. Let your shoulder relax towards the floor.', array['On hands and knees.', 'Slide one arm under your body.', 'Return and reach that arm to the ceiling.']::text[], 'Smaller range', null, array['mobility']::text[]) on conflict (id) do nothing;
insert into public.exercises (id, business_id, name, video_length, coaching_notes, steps, easier, harder, tags) values ('fd39f5c0-7014-569b-a8b0-ff1a7c67880d', '7a1e5b0d-0000-4000-a000-000000000001', 'Hip flexor stretch', '0:25', 'Tuck your tail under and you will feel the stretch at the front of the back hip.', array['Kneel on one knee with a cushion.', 'Tuck your pelvis under.', 'Shift forward gently.', 'Hold and breathe.']::text[], 'Standing version holding a chair', null, array['mobility']::text[]) on conflict (id) do nothing;
insert into public.exercises (id, business_id, name, video_length, coaching_notes, steps, easier, harder, tags) values ('97568a3a-0c79-58ea-a604-916ac86f7fc4', '7a1e5b0d-0000-4000-a000-000000000001', 'Sit to stand', '0:24', 'Feet back slightly, lean forward and stand up tall. Sit down slowly, no flopping.', array['Sit near the front of a sturdy chair.', 'Feet flat, slightly behind your knees.', 'Lean forward and stand up.', 'Sit down slowly.']::text[], 'Use your hands on your thighs', 'Hold a light weight', array['legs', 'strength', 'senior']::text[]) on conflict (id) do nothing;
insert into public.exercises (id, business_id, name, video_length, coaching_notes, steps, easier, harder, tags) values ('ca50e2e4-c00f-55de-a10e-ad1383b2439c', '7a1e5b0d-0000-4000-a000-000000000001', 'Heel to toe walk', '0:20', 'Keep one hand on the kitchen counter. Look ahead, not at your feet.', array['Stand beside the counter.', 'Place one heel in front of the other toe.', 'Take 10 slow steps.', 'Turn and come back.']::text[], 'Feet slightly apart', 'Without holding on', array['balance', 'senior']::text[]) on conflict (id) do nothing;
insert into public.exercises (id, business_id, name, video_length, coaching_notes, steps, easier, harder, tags) values ('980c0bdf-8b71-5bfa-aeaa-d5129ec417be', '7a1e5b0d-0000-4000-a000-000000000001', 'Single-leg balance', '0:16', 'Hold the counter lightly. Stand tall and keep a soft knee.', array['Stand beside the counter.', 'Lift one foot just off the floor.', 'Hold for up to 30 seconds.', 'Swap legs.']::text[], 'Toes on the floor for support', 'Eyes closed, still holding on', array['balance', 'senior']::text[]) on conflict (id) do nothing;
insert into public.exercises (id, business_id, name, video_length, coaching_notes, steps, easier, harder, tags) values ('e5bb9008-b226-5638-a337-c40cb04452b8', '7a1e5b0d-0000-4000-a000-000000000001', 'Seated knee extension', '0:14', 'Straighten your leg slowly and squeeze the front of your thigh for a second.', array['Sit tall in a chair.', 'Straighten one knee.', 'Hold for a second.', 'Lower slowly.']::text[], null, 'Add an ankle weight', array['rehab', 'senior']::text[]) on conflict (id) do nothing;
insert into public.exercises (id, business_id, name, video_length, coaching_notes, steps, easier, harder, tags) values ('e2847086-198d-5592-a7d3-1902f5fb747d', '7a1e5b0d-0000-4000-a000-000000000001', 'Banded clam', '0:15', 'Keep your feet together and your hips stacked. Open the knee like a clam shell.', array['Lie on your side, knees bent, band above knees.', 'Keep feet together.', 'Lift the top knee.', 'Lower slowly.']::text[], 'No band', 'Thicker band', array['rehab']::text[]) on conflict (id) do nothing;
insert into public.exercises (id, business_id, name, video_length, coaching_notes, steps, easier, harder, tags) values ('fa314330-f8e5-5b0f-aefe-00148d5c78b2', '7a1e5b0d-0000-4000-a000-000000000001', 'Jumping jacks', '0:10', 'Land softly on the balls of your feet.', array['Jump feet out and arms up.', 'Jump back in.']::text[], 'Step out instead of jumping', null, array['cardio']::text[]) on conflict (id) do nothing;
insert into public.exercises (id, business_id, name, video_length, coaching_notes, steps, easier, harder, tags) values ('abb9662e-07c1-588d-a583-7fa5d3eb1700', '7a1e5b0d-0000-4000-a000-000000000001', 'Squat thrust', '0:12', 'Hands down, step or jump back to a plank, then return and stand.', array['Squat and place hands down.', 'Step or jump back.', 'Return and stand up.']::text[], 'Step back one leg at a time', 'Add a jump at the top', array['cardio']::text[]) on conflict (id) do nothing;
