insert into public.exercises (id, business_id, name, video_length, coaching_notes, steps, easier, harder, tags) values ('eefa6898-7a1a-570e-ad59-ba9bc19b8754', '7a1e5b0d-0000-4000-a000-000000000001', 'Arm circles', '0:10', 'Small circles first, then bigger. Keep your shoulders relaxed.', array['Arms out to the side.', 'Make small circles forwards.', 'Then backwards.']::text[], 'One arm at a time', null, array['mobility', 'warm-up']::text[]) on conflict (id) do nothing;
